+    unsigned field;
+    wmem_strbuf_t *str;
+
+    str = wmem_strbuf_create(NULL);
+    for (field = 0; field < uat->ncols; field++) {
+        char *fld = uat_fld_tostr(rec, &(uat->fields[field]));
+        if (field > 0)
+            wmem_strbuf_append_c(str, ',');
+        wmem_strbuf_append_printf(str, "\"%s\"", fld);
+        g_free(fld);
+    }
+    return (wmem_strbuf_finalize(str));
+}
